import heapq

def topo_sort(n, edges):
    indegree = [0] * n
    adjacency = [[] for _ in range(n)]
    for a, b in edges:
        adjacency[a].append(b)
        indegree[b] += 1
    heap = [node for node in range(n) if indegree[node] == 0]
    heapq.heapify(heap)
    order = []
    while heap:
        node = heapq.heappop(heap)
        order.append(node)
        for neighbor in adjacency[node]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                heapq.heappush(heap, neighbor)
    if len(order) != n:
        raise ValueError('graph contains a cycle')
    return order

def allowed_requests(timestamps, window, limit):
    allowed_times = []
    decisions = []
    for t in timestamps:
        recent = sum(1 for a in allowed_times if a > t - window)
        if recent < limit:
            decisions.append(True)
            allowed_times.append(t)
        else:
            decisions.append(False)
    return decisions

