def resolve_path(base, relative):
    if not isinstance(base, str) or not isinstance(relative, str):
        raise TypeError('paths must be strings')
    if relative.startswith('/'):
        raise ValueError('relative path must not be absolute')
    parts = []
    for segment in relative.split('/'):
        if segment in ('', '.'):
            continue
        if segment == '..':
            if not parts:
                raise ValueError('path escapes the base directory')
            parts.pop()
        else:
            parts.append(segment)
    if not parts:
        return base
    return base + '/' + '/'.join(parts)

