import re

_NAME_RE = re.compile(r'[A-Za-z0-9_]+\Z')

def render(template, values):
    out = []
    i = 0
    n = len(template)
    while i < n:
        ch = template[i]
        if ch == '{':
            if i + 1 < n and template[i + 1] == '{':
                out.append('{')
                i += 2
                continue
            end = template.find('}', i + 1)
            if end == -1:
                raise ValueError('unclosed placeholder')
            name = template[i + 1:end]
            if not _NAME_RE.match(name):
                raise ValueError(f'invalid placeholder name: {name!r}')
            if name not in values:
                raise KeyError(name)
            out.append(str(values[name]))
            i = end + 1
        elif ch == '}':
            if i + 1 < n and template[i + 1] == '}':
                out.append('}')
                i += 2
                continue
            raise ValueError("stray '}' in template")
        else:
            out.append(ch)
            i += 1
    return ''.join(out)

import bisect

def lis_length(nums):
    tails = []
    for x in nums:
        pos = bisect.bisect_left(tails, x)
        if pos == len(tails):
            tails.append(x)
        else:
            tails[pos] = x
    return len(tails)

import re

_INT_RE = re.compile(r'-?\d+\Z')

def _coerce(value):
    if _INT_RE.match(value):
        return int(value)
    if value.lower() == 'true':
        return True
    if value.lower() == 'false':
        return False
    return value

def parse_config(text):
    result = {}
    section = 'default'
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith('#'):
            continue
        if line.startswith('['):
            if not line.endswith(']'):
                raise ValueError(f'malformed section header: {raw!r}')
            section = line[1:-1].strip()
            continue
        if '=' not in line:
            raise ValueError(f'malformed line: {raw!r}')
        key, _, value = line.partition('=')
        key = key.strip()
        if not key:
            raise ValueError(f'empty key in line: {raw!r}')
        result.setdefault(section, {})[key] = _coerce(value.strip())
    return result

