import re

_TOKEN_RE = re.compile(r'\s*(?:(\d+(?:\.\d+)?)|([()+\-*/]))')

def _tokenize(expr):
    tokens = []
    i = 0
    while i < len(expr):
        match = _TOKEN_RE.match(expr, i)
        if not match:
            if expr[i:].strip() == '':
                break
            raise ValueError(f'invalid character in expression at index {i}')
        if match.group(1) is not None:
            tokens.append(float(match.group(1)))
        else:
            tokens.append(match.group(2))
        i = match.end()
    return tokens

def eval_expr(expr):
    if not isinstance(expr, str):
        raise TypeError('expression must be a string')
    tokens = _tokenize(expr)
    pos = 0

    def parse_expression():
        nonlocal pos
        value = parse_term()
        while pos < len(tokens) and tokens[pos] in ('+', '-'):
            op = tokens[pos]
            pos += 1
            rhs = parse_term()
            value = value + rhs if op == '+' else value - rhs
        return value

    def parse_term():
        nonlocal pos
        value = parse_factor()
        while pos < len(tokens) and tokens[pos] in ('*', '/'):
            op = tokens[pos]
            pos += 1
            rhs = parse_factor()
            value = value * rhs if op == '*' else value / rhs
        return value

    def parse_factor():
        nonlocal pos
        if pos >= len(tokens):
            raise ValueError('unexpected end of expression')
        token = tokens[pos]
        if token == '-':
            pos += 1
            return -parse_factor()
        if token == '(':
            pos += 1
            value = parse_expression()
            if pos >= len(tokens) or tokens[pos] != ')':
                raise ValueError('missing closing parenthesis')
            pos += 1
            return value
        if isinstance(token, float):
            pos += 1
            return token
        raise ValueError(f'unexpected token: {token!r}')

    result = parse_expression()
    if pos != len(tokens):
        raise ValueError('unexpected trailing input')
    return float(result)
